{"script":"cat > count_logs.sh <<'EOF'
#!/bin/bash
if [ $# -ne 1 ]; then echo "Usage: $0 YYYY-MM" >&2; exit 2; fi
cd logs || { echo "logs dir not found" >&2; exit 1; }
find . -maxdepth 1 -type f -name "$1-??.log" | wc -l
